project.dependencies:

      org.springframework.boot
      spring-boot-starter

{% if framework != 'spring-boot-batch' %}

      org.springframework.boot
      spring-boot-starter-web

{% endif %}
{% if 'batch' in framework %}

      org.springframework.boot
      spring-boot-starter-batch

{% endif %}
{% if db == 'h2' %}

      com.h2database
      h2
      runtime

{% elif db == 'postgres' %}

      org.postgresql
      postgresql
      runtime

{% elif db == 'mysql' %}

      com.mysql
      mysql-connector-j
      runtime

{% endif %}
{% if db != 'h2' %}


      com.h2database
      h2
      test

{% endif %}
{% if migrations == 'flyway' %}

      org.flywaydb
      flyway-core

{% if db == 'postgres' %}

      org.flywaydb
      flyway-database-postgresql

{% endif %}
{% elif migrations == 'liquibase' %}

      org.liquibase
      liquibase-core

{% endif %}
{% if use_security %}

      org.springframework.boot
      spring-boot-starter-security

{% endif %}
{% if use_observability %}

      org.springframework.boot
      spring-boot-starter-actuator


      io.micrometer
      micrometer-registry-prometheus
      runtime

{% endif %}

      org.springframework.boot
      spring-boot-starter-test
      test

{% if 'batch' in framework %}

      org.springframework.batch
      spring-batch-test
      test

{% endif %}
{% if use_testcontainers %}

      org.springframework.boot
      spring-boot-testcontainers
      test


      org.testcontainers
      junit-jupiter
      test

{% if db == 'postgres' %}

      org.testcontainers
      postgresql
      test

{% endif %}
{% endif %}
{% if use_archunit %}

      com.tngtech.archunit
      archunit-junit5
      ${archunit.version}
      test

{% endif %}
